-- Fixture F152 (SPEC-152 Amendment F test plan). DISPOSABLE CLONE ONLY: the harness asserts SELECT current_schema() = the clone name first.
-- Column lists were checked against src/db/schema/*.ts on 2026-10-29; the first run reports any NOT NULL column the schema gained since.
-- Every id starts f1520000- so teardown-f152.sql can remove exactly these rows.
BEGIN;
-- password is a placeholder, never a working hash: sign-in items set a real bcrypt hash through the harness.
-- whole-Project assignments have scopeid and taskid NULL; P-C1-D carries a scope-level assignment only; P-C1-B has none.
COMMIT;
-- Expected after load: 4 companies, 8 users, 8 projects, 1 projectuser, 2 invitations, 2 engagements, 4 assignments, 1 subassignment (all with the f1520000- prefix).
SELECT (SELECT count(*) FROM companies WHERE id::text LIKE 'f1520000-%') AS companies, (SELECT count(*) FROM userprofiles WHERE id::text LIKE 'f1520000-%') AS users, (SELECT count(*) FROM companyprojects WHERE id::text LIKE 'f1520000-%') AS projects, (SELECT count(*) FROM engagementassignments WHERE id::text LIKE 'f1520000-%') AS assignments;
